package com.jnapanam.sportszone.notification.controller;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/notifications/whatsapp-consent")public class WhatsAppConsentController{private final JdbcTemplate j;public WhatsAppConsentController(JdbcTemplate j){this.j=j;}@GetMapping public Map<String,Object> get(Authentication a){UUID u=UUID.fromString(a.getName());List<Boolean> rows=j.query("select coalesce(whatsapp_enabled,false) from notification_preferences where user_id=?",(rs,n)->rs.getBoolean(1),u);return Map.of("enabled",!rows.isEmpty()&&Boolean.TRUE.equals(rows.get(0)));}@PutMapping public Map<String,Object> put(Authentication a,@RequestBody Map<String,Object>b){UUID u=UUID.fromString(a.getName());boolean enabled=Boolean.parseBoolean(String.valueOf(b.getOrDefault("enabled",false)));j.update("insert into notification_preferences(user_id,email_enabled,sms_enabled,push_enabled,whatsapp_enabled,whatsapp_consented_at) values(?,true,false,true,?,case when ? then now() else null end) on conflict(user_id) do update set whatsapp_enabled=excluded.whatsapp_enabled,whatsapp_consented_at=excluded.whatsapp_consented_at",u,enabled,enabled);j.update("insert into whatsapp_consent_history(id,user_id,enabled) values(?,?,?)",UUID.randomUUID(),u,enabled);return Map.of("enabled",enabled);}}
